    SavingsOpportunity = apps.get_model("pricing", "SavingsOpportunity")
    AuditReview = apps.get_model("pricing", "AuditReview")

    legacy_ids = set(PlanAudit.objects.filter(
        status__in=("running", "completed", "needs_review", "failed")
    ).values_list("pk", flat=True))
    legacy_ids.update(PlanAuditResult.objects.values_list("plan_audit_id", flat=True))
    legacy_ids.update(SavingsOpportunity.objects.values_list("plan_audit_id", flat=True))
    legacy_ids.update(AuditReview.objects.values_list("plan_audit_id", flat=True))
    legacy_ids.update(PlanAudit.objects.filter(report_generated_at__isnull=False)
                      .values_list("pk", flat=True))

    for audit in PlanAudit.objects.filter(pk__in=legacy_ids).iterator():
        run = PlanAuditRun.objects.create(
            plan_audit_id=audit.pk,
            version=1,
            calculation_status="legacy_unverified",
            publication_status="unverified",
            summary_import_id=audit.summary_import_id,
            source_sha256=audit.summary_import.file_hash,
            initiated_by_id=audit.created_by_id,
            review_status="unverified",
            started_at=audit.created_at,
            completed_at=audit.completed_at,
        )
        PlanAudit.objects.filter(pk=audit.pk).update(current_version=1, published_version=None)
        PlanAuditResult.objects.filter(plan_audit_id=audit.pk).update(audit_run_id=run.pk)
        SavingsOpportunity.objects.filter(plan_audit_id=audit.pk).update(audit_run_id=run.pk)
        AuditReview.objects.filter(plan_audit_id=audit.pk).update(audit_run_id=run.pk)


